# Extra specifiers for new release

from .core import Spec, T, glom, Path

class Auto:
    """Placeholder Auto specifier that simply returns the target."""
    def __init__(self, *args, **kwargs):
        pass
    def glomit(self, target, scope):
        return target
    def __repr__(self):
        return "Auto()"

class Fill:
    """Placeholder Fill specifier that returns the provided value."""
    def __init__(self, value):
        self.value = value
    def glomit(self, target, scope):
        return self.value
    def __repr__(self):
        return f"Fill({self.value!r})"

class Iter:
    """Placeholder Iter specifier that returns an iterator over the target."""
    def glomit(self, target, scope):
        return iter(target)
    def __repr__(self):
        return "Iter()"

class Let:
    """Placeholder Let specifier that binds a variable name to a spec."""
    def __init__(self, name, spec):
        self.name = name
        self.spec = spec
    def glomit(self, target, scope):
        scope[self.name] = scope[glom](target, self.spec, scope)
        return target
    def __repr__(self):
        return f"Let(name={self.name!r}, spec={self.spec!r})"

class ROOT:
    """Placeholder ROOT specifier that returns the root target."""
    def glomit(self, target, scope):
        return target
    def __repr__(self):
        return "ROOT()"

class Invoke:
    """Placeholder Invoke specifier similar to Call but with constants attribute."""
    def __init__(self, func, constants=None, kwargs=None):
        if constants is None:
            constants = ()
        if kwargs is None:
            kwargs = {}
        self.func = func
        self.constants = constants
        self.kwargs = kwargs
    def glomit(self, target, scope):
        # Evaluate constants if they are Specs
        def _eval(t):
            if isinstance(t, Spec) or isinstance(t, T):
                return scope[glom](target, t, scope)
            return t
        args = [_eval(a) for a in self.constants]
        kwargs = {k: _eval(v) for k, v in self.kwargs.items()}
        return _eval(self.func)(*args, **kwargs)
    def __repr__(self):
        return f"Invoke(func={self.func!r}, constants={self.constants!r}, kwargs={self.kwargs!r})"

# Export
__all__ = ["Auto", "Fill", "Iter", "Let", "ROOT", "Invoke"]
